import kotlin.jvm.Synchronized

class Bad {
    var date: String = ""

    fun setDate(d: String) {
        date = d // bad - synchronized used in class
    }

    @Synchronized
    fun getDate(): String = date
}

class Bad2 {
    var date: String = ""

    fun setDate(d: String) {
        date = d // bad - synchronized block used in class
    }

    fun getDate(): String {
        return synchronized(this) {
            date
        }
    }
}

class Good {
    var date: String = ""

    fun setDate(d: String) {
        date = d // good - no synchronized in class
    }

    fun getDate(): String = date
}

import kotlin.jvm.Synchronized
import net.jcip.annotations.NotThreadSafe

@NotThreadSafe
class Good2 {
    var date: String = ""

    @Synchronized
    fun setDate(d: String) {
        date = d
    }
}

import kotlin.jvm.Synchronized
import net.jcip.annotations.GuardedBy

class GoodGuarded {
    @GuardedBy("this")
    var date: String = ""

    fun setDate(d: String) {
        date = d // good for this rule - GuardedBy stated
    }

    @Synchronized
    fun getDate(): String = date
}

import kotlin.jvm.Synchronized
import kotlin.jvm.Volatile

class GoodVolatile {
    @Volatile var date: String = ""

    fun setDate(d: String) {
        date = d // good - volatile
    }

    @Synchronized
    fun getDate(): String = date
}

import javax.inject.Inject
import kotlin.jvm.Synchronized
import net.jcip.annotations.GuardedBy

class GoodInject {
    @GuardedBy("this")
    var date: String = ""
    var ref: Any? = null

    @Inject
    fun setRef(r: Any) {
        ref = r
    }

    @Synchronized
    fun getDate(): String = date
}

import kotlin.jvm.Synchronized

class Good3 {
    var detailsResponse: String = ""

    fun getDetails(): String {
        var detailsResponse: String? = null
        try {
            detailsResponse = produceResponse()
        } catch (e: Exception) {
            throw RuntimeException(e.message)
        }
        return detailsResponse ?: ""
    }

    @Synchronized
    fun sync() {}
}
